-- PASSO 4 - Resoluções de Contabilidade Pública/AFO/Direito Financeiro - parte 2 (373).
BEGIN;
UPDATE questoes SET resolution='{"what_it_tests": "Reconhecer a finalidade da Demonstração das Variações Patrimoniais.", "rule": "A DVP evidencia as alterações verificadas no patrimônio, resultantes ou independentes da execução orçamentária, e indica o resultado patrimonial do exercício.", "reasoning": ["A descreve o Balanço Orçamentário.", "B descreve o Balanço Patrimonial.", "C descreve a DVP.", "D descreve o Balanço Financeiro."], "calculation": "Não há cálculo.", "correct_answer": "C — evidencia as alterações verificadas no patrimônio e indica o resultado patrimonial.", "why_wrong": "A, B e D correspondem a outras demonstrações contábeis aplicadas ao setor público.", "basis": "Lei nº 4.320/1964, art. 104; MCASP/DCASP.", "fafipa_trap": "A expressão “resultantes ou independentes da execução orçamentária” é característica da DVP.", "verification": null}'::jsonb WHERE id='2156993';
UPDATE questoes SET resolution='{"what_it_tests": "Calcular o Resultado Patrimonial do Período.", "rule": "Resultado patrimonial = VPA − VPD.", "reasoning": ["VPA = transferências recebidas 500.000 + impostos 680.000 + contribuições de melhoria 360.000 = R$ 1.540.000.", "VPD = pessoal 445.000 + juros 32.000 + aposentadorias 170.000 + material 648.000 = R$ 1.295.000.", "Resultado = 1.540.000 − 1.295.000 = R$ 245.000."], "calculation": "R$ 1.540.000 − R$ 1.295.000 = R$ 245.000.", "correct_answer": "A — R$ 245.000,00.", "why_wrong": "B, C e D não correspondem ao confronto correto entre VPA e VPD.", "basis": "MCASP/DCASP — Demonstração das Variações Patrimoniais.", "fafipa_trap": "Juros pagos e despesas com pessoal são VPD; impostos e transferências recebidas são VPA.", "verification": null}'::jsonb WHERE id='2156996';
UPDATE questoes SET resolution='{"what_it_tests": "Identificar a demonstração contábil que evidencia as variações patrimoniais.", "rule": "A DVP evidencia as alterações no patrimônio, resultantes ou independentes da execução orçamentária, e apresenta o resultado patrimonial.", "reasoning": ["A, B e C são demonstrações diferentes ou não correspondem à descrição.", "A descrição dada é a definição da DVP."], "calculation": "Não há cálculo.", "correct_answer": "D — Demonstração das Variações Patrimoniais.", "why_wrong": "As demais alternativas não possuem a finalidade descrita no enunciado.", "basis": "Lei nº 4.320/1964, art. 104; MCASP/DCASP.", "fafipa_trap": "A expressão “variações patrimoniais quantitativas aumentativas e diminutivas” aponta diretamente para a DVP.", "verification": null}'::jsonb WHERE id='2431269';
UPDATE questoes SET resolution='{"what_it_tests": "Calcular o resultado financeiro do exercício pelo Balanço Financeiro.", "rule": "Quando o Balanço Financeiro apresenta saldo em espécie inicial e final, o resultado financeiro pode ser obtido pela diferença entre o saldo final e o saldo inicial.", "reasoning": ["Saldo final = R$ 4.709.600.", "Saldo inicial = R$ 1.820.000.", "Resultado financeiro = 4.709.600 − 1.820.000 = R$ 2.889.600."], "calculation": "R$ 4.709.600 − R$ 1.820.000 = R$ 2.889.600.", "correct_answer": "E — R$ 2.889.600,00.", "why_wrong": "A, B, C e D não correspondem à variação entre os saldos em espécie apresentados.", "basis": "MCASP — Balanço Financeiro; Lei nº 4.320/1964, art. 103.", "fafipa_trap": "O resultado financeiro não é simplesmente receita orçamentária menos despesa orçamentária; o BF considera todos os fluxos e saldos financeiros.", "verification": null}'::jsonb WHERE id='2153503';
UPDATE questoes SET resolution='{"what_it_tests": "Calcular o resultado financeiro a partir da variação do saldo de caixa/equivalentes.", "rule": "Resultado financeiro do exercício = saldo final em espécie − saldo inicial em espécie.", "reasoning": ["Saldo final = R$ 460.000.", "Saldo inicial = R$ 420.000.", "Resultado = 460.000 − 420.000 = R$ 40.000.", "A inscrição e o pagamento de restos a pagar são componentes do BF, mas a variação dos saldos já permite obter o resultado financeiro."], "calculation": "R$ 460.000 − R$ 420.000 = R$ 40.000.", "correct_answer": "A — R$ 40.000,00.", "why_wrong": "B, C e D não correspondem à variação dos saldos em espécie.", "basis": "MCASP — Balanço Financeiro; Lei nº 4.320/1964, art. 103.", "fafipa_trap": "Não confundir R$ 50.000 de diferença entre inscrição e pagamento de RP com o resultado financeiro: o resultado é R$ 40.000 pela variação do saldo de caixa.", "verification": null}'::jsonb WHERE id='2156995';
UPDATE questoes SET resolution='{"what_it_tests": "Calcular o resultado financeiro do Balanço Financeiro a partir de ingressos e dispêndios.", "rule": "O resultado financeiro decorre do confronto entre ingressos e dispêndios financeiros, considerando a classificação das rubricas no Balanço Financeiro.", "reasoning": ["O enunciado apresenta recursos vinculados, recursos destinados, transferências, ingressos ordinários, dispêndios ordinários e restos a pagar.", "A extração textual não preserva a estrutura/colunas do Balanço Financeiro, o que impede determinar com segurança quais valores devem compor ingressos e quais devem compor dispêndios.", "Por isso, não é seguro reproduzir o cálculo do gabarito D apenas com o texto extraído."], "calculation": "Não é seguro fechar o cálculo com os dados na forma textual disponível.", "correct_answer": "D — R$ 490.000,00, conforme gabarito registrado.", "why_wrong": "Não é possível justificar matematicamente as demais alternativas sem recuperar a apresentação original das rubricas.", "basis": "MCASP — Balanço Financeiro; Lei nº 4.320/1964, art. 103.", "fafipa_trap": "Em questões de BF, a posição da rubrica no quadro importa. Não reconstruir a tabela apenas por palavras soltas na extração.", "verification": "Conferir o PDF original antes de transformar esta questão em exemplo de cálculo."}'::jsonb WHERE id='2431273';
UPDATE questoes SET resolution='{"what_it_tests": "Classificar assertivas sobre disposições constitucionais do orçamento.", "rule": "CF/88: PPA, LDO e LOA são leis de iniciativa do Executivo; a LOA contém os três orçamentos; o projeto é acompanhado do demonstrativo regionalizado de renúncias e benefícios; lei complementar trata de normas de gestão financeira; projetos orçamentários são apreciados pelas duas Casas.", "reasoning": ["1ª: Falsa. A CF determina apreciação pelos mecanismos do Congresso, não pelo Conselho Nacional de Justiça.", "2ª: Falsa. A LOA compreende orçamento fiscal, orçamento de investimento e orçamento da seguridade social; a assertiva omite este último e usa “apenas”.", "3ª: Verdadeira. O projeto de LOA é acompanhado do demonstrativo regionalizado previsto no art. 165, § 6º.", "4ª: Verdadeira. O art. 165, § 9º, II, reserva à lei complementar normas de gestão financeira e patrimonial e condições para instituição e funcionamento de fundos.", "5ª: Verdadeira. O art. 166 prevê apreciação pelas duas Casas do Congresso, na forma do regimento comum."], "calculation": "Não há cálculo.", "correct_answer": "B — F-F-V-V-V.", "why_wrong": "A, C e D alteram pelo menos uma das cinco classificações.", "basis": "Constituição Federal, arts. 165 e 166.", "fafipa_trap": "Palavras absolutas como “apenas” e troca do órgão competente costumam derrubar a assertiva.", "verification": "Fundamento conferido na CF/88."}'::jsonb WHERE id='2163427';
UPDATE questoes SET resolution='{"what_it_tests": "Julgar assertivas constitucionais sobre PPA, LDO, LOA e processo legislativo orçamentário.", "rule": "As três leis são de iniciativa do Executivo; o demonstrativo de renúncias acompanha a LOA; a regra da exclusividade admite créditos suplementares e operações de crédito nos termos legais; o art. 165, § 12, trata do anexo de agregados fiscais; os projetos são apreciados pelas duas Casas.", "reasoning": ["I: Verdadeira.", "II: Verdadeira.", "III: Verdadeira.", "IV: Falsa. O texto fala em pelo menos quatro exercícios subsequentes; o art. 165, § 12, atualmente prevê pelo menos dois exercícios subsequentes.", "V: Falsa. O art. 166 determina apreciação pelas duas Casas do Congresso."], "calculation": "Não há cálculo.", "correct_answer": "D — V-V-V-F-F.", "why_wrong": "A, B e C apresentam sequências incompatíveis com as cinco assertivas.", "basis": "Constituição Federal, arts. 165 e 166.", "fafipa_trap": "Cuidado com números alterados na literalidade constitucional: “4” não é “2”.", "verification": "Conferido com o texto constitucional vigente; a questão é histórica, mas a assertiva IV permanece falsa."}'::jsonb WHERE id='1643137';
UPDATE questoes SET resolution='{"what_it_tests": "Calcular o resultado patrimonial e separar VPA de VPD na DVP.", "rule": "Resultado patrimonial = VPA − VPD. As variações aumentativas e diminutivas devem ser classificadas conforme sua natureza patrimonial.", "reasoning": ["Somando as VPA: 2.542.500.", "Somando as VPD: 2.274.400.", "Resultado patrimonial = 2.542.500 − 2.274.400 = 268.100.", "Logo, I e II são verdadeiras e III é falsa."], "calculation": "VPA = R$ 2.542.500; VPD = R$ 2.274.400; resultado = R$ 268.100.", "correct_answer": "D — I e II, apenas.", "why_wrong": "A, B e C incluem a assertiva III, que informa VPD de R$ 2.419.400, valor incompatível com a soma dos dados. E exclui o resultado patrimonial correto.", "basis": "MCASP — Demonstração das Variações Patrimoniais; Lei nº 4.320/1964, art. 104.", "fafipa_trap": "Não confundir saldo de VPD com resultado patrimonial: primeiro se somam as classes, depois se confrontam VPA e VPD.", "verification": "Cálculo reproduzido a partir dos valores do enunciado."}'::jsonb WHERE id='1741152';
UPDATE questoes SET resolution='{"what_it_tests": "Reconstruir o Balanço Financeiro e calcular saldo inicial, despesas, extraorçamentários e resultado financeiro.", "rule": "No BF, o saldo final decorre do saldo inicial somado aos ingressos e deduzido dos dispêndios; inscrição de restos a pagar integra os recebimentos extraorçamentários, e pagamentos de RP integram os dispêndios extraorçamentários.", "reasoning": ["Receita orçamentária = 1.100.200 + 890.100 = 1.990.300.", "Despesa orçamentária = 760.300 + 830.600 = 1.590.900.", "Recebimentos extraorçamentários identificáveis = inscrições de RPNP 280.900 + inscrições de RPP 260.400 + valores restituíveis 59.700 = 601.000.", "Pagamentos extraorçamentários = RPP 180.800 + RPNP 210.200 + valores restituíveis 32.300 = 423.300.", "Aplicando a equação do BF aos valores extraídos, há diferença de R$ 1.000 em relação ao saldo inicial declarado pelo gabarito. Por isso, o item I não pode ser validado matematicamente com total segurança.", "Os itens II, IV e V também não formam uma combinação limpa com os valores extraídos; o gabarito E deve ser conferido no original."], "calculation": "Com a extração textual: receita orçamentária R$ 1.990.300; despesa orçamentária R$ 1.590.900; recebimentos extraorçamentários R$ 601.000; pagamentos extraorçamentários R$ 423.300. A estrutura não fecha exatamente o gabarito.", "correct_answer": "E — I, IV e V, apenas, conforme gabarito registrado; há inconsistência de R$ 1.000 na reconstrução textual.", "why_wrong": "Não é seguro rejeitar individualmente todas as demais alternativas porque a extração pode ter perdido uma rubrica/valor.", "basis": "Lei nº 4.320/1964, art. 103; MCASP — Balanço Financeiro.", "fafipa_trap": "Em BF, inscrição de RP e pagamento de RP afetam os ingressos/dispêndios extraorçamentários.", "verification": "Conferir o quadro original antes de usar esta questão como exemplo fechado."}'::jsonb WHERE id='1741131';
UPDATE questoes SET resolution='{"what_it_tests": "Calcular VPA, VPD e resultado patrimonial na DVP.", "rule": "Resultado patrimonial = VPA − VPD.", "reasoning": ["VPA = 180.800 + 1.260 + 230 + 150 + 14.840 + 2.300 + 58.320 + 11.330 = 269.230.", "VPD = 111.920 + 580 + 130 + 3.370 + 15.880 + 2.770 + 770 + 170 + 16.970 + 50.430 = 202.990.", "Resultado = 269.230 − 202.990 = 66.240.", "As três assertivas estão corretas."], "calculation": "VPA = R$ 269.230 mil; VPD = R$ 202.990 mil; resultado = R$ 66.240 mil.", "correct_answer": "E — I, II e III.", "why_wrong": "As demais alternativas omitem pelo menos uma assertiva que é confirmada pelos cálculos.", "basis": "MCASP — DVP.", "fafipa_trap": "A questão informa os valores “em milhares de reais”; o cálculo mantém a mesma unidade.", "verification": "Cálculo reproduzido."}'::jsonb WHERE id='2165657';
UPDATE questoes SET resolution='{"what_it_tests": "Calcular o saldo em espécie do exercício anterior no Balanço Financeiro.", "rule": "Saldo final = saldo inicial + ingressos − dispêndios. A inscrição de restos a pagar processados aparece nos ingressos extraorçamentários.", "reasoning": ["Ingressos = receita vinculada 1.100.000 + receita ordinária 770.000 + transferências recebidas 1.300.000 + ingresso de valores restituíveis 33.000 + inscrição de RPP 88.000 = 3.291.000.", "Dispêndios = despesas vinculada 880.000 + ordinária 540.000 + pagamentos de RPP 177.000 + dispêndios restituíveis 66.000 = 1.663.000.", "Saldo inicial = 1.998.000 − 3.291.000 + 1.663.000 = 370.000."], "calculation": "R$ 1.998.000 − (R$ 3.291.000 − R$ 1.663.000) = R$ 370.000.", "correct_answer": "A — R$ 370.000,00.", "why_wrong": "B, C e D não satisfazem a equação do Balanço Financeiro com a inscrição de RP classificada como ingresso extraorçamentário.", "basis": "Lei nº 4.320/1964, art. 103; MCASP — Balanço Financeiro.", "fafipa_trap": "A inscrição de restos a pagar não representa uma nova receita orçamentária; no BF ela aparece como ingresso extraorçamentário.", "verification": "Cálculo reproduzido."}'::jsonb WHERE id='1972632';
UPDATE questoes SET resolution='{"what_it_tests": "Identificar afirmação incorreta sobre LDO e ciclo orçamentário.", "rule": "O sistema orçamentário brasileiro possui PPA, LDO e LOA. A LDO orienta a LOA e estabelece metas e prioridades, entre outras funções.", "reasoning": ["A descreve o processo federal de elaboração e envio do projeto de LOA.", "B apresenta a ideia geral do orçamento anual.", "C é incorreta: não existe apenas uma lei orçamentária chamada LDO; existem PPA, LDO e LOA, com funções e horizontes distintos.", "D e E descrevem etapas do processo legislativo e de execução."], "calculation": "Não há cálculo.", "correct_answer": "C — é a afirmação incorreta.", "why_wrong": "A, B, D e E não apresentam a inversão central encontrada na alternativa C.", "basis": "Constituição Federal, arts. 165 e 166.", "fafipa_trap": "Não confundir LDO com o conjunto das leis orçamentárias.", "verification": "Conferido com a CF/88."}'::jsonb WHERE id='990584';
UPDATE questoes SET resolution='{"what_it_tests": "Identificar a alternativa correta sobre PPA, LDO e LOA.", "rule": "A LOA deve ser acompanhada do demonstrativo regionalizado do efeito de renúncias e benefícios, conforme art. 165, § 6º.", "reasoning": ["A reproduz o art. 165, § 6º.", "B é falsa porque iniciativa das leis orçamentárias é do Executivo e LDO não fixa a despesa nem prevê receita como a LOA.", "C atribui ao PPA conteúdos típicos da LRF/LDO.", "D é falsa porque a exceção constitucional à regra de exclusividade inclui autorização para créditos suplementares e operações de crédito, não créditos especiais."], "calculation": "Não há cálculo.", "correct_answer": "A.", "why_wrong": "B, C e D contêm erros sobre iniciativa, conteúdo e exceções ao princípio da exclusividade.", "basis": "Constituição Federal, art. 165, §§ 2º e 6º; art. 167, V.", "fafipa_trap": "A banca troca “créditos suplementares” por “créditos especiais” na exceção ao princípio da exclusividade.", "verification": "Conferido com a CF/88."}'::jsonb WHERE id='1058808';
UPDATE questoes SET resolution='{"what_it_tests": "Calcular resultado patrimonial a partir das VPA e VPD da DVP.", "rule": "Resultado patrimonial = total das VPA − total das VPD.", "reasoning": ["VPA = 522.770 + 123.450 + 265.480 + 99.750 + 240.230 + 49.990 = 1.301.670.", "VPD = 162.610 + 12.180 + 26.400 + 168.160 = 369.350.", "Resultado = 1.301.670 − 369.350 = 932.320."], "calculation": "R$ 1.301.670 − R$ 369.350 = R$ 932.320.", "correct_answer": "B — R$ 932.320,00.", "why_wrong": "Os demais valores não correspondem ao confronto dos totais de VPA e VPD.", "basis": "MCASP — DVP.", "fafipa_trap": "Somar ganhos de alienação aos demais componentes de VPA e não tratá-los como receita orçamentária para esse cálculo patrimonial.", "verification": "Cálculo reproduzido."}'::jsonb WHERE id='1335901';
UPDATE questoes SET resolution='{"what_it_tests": "Calcular itens do Balanço Financeiro de um RPPS.", "rule": "Receitas orçamentárias são ingressos orçamentários; despesas orçamentárias são os gastos orçamentários; resultado financeiro é a variação do saldo em espécie.", "reasoning": ["I é falsa: receita orçamentária = receita patrimonial 1.740.300 + contribuições sociais 5.220.100 = 6.960.400.", "II é verdadeira: despesa = pensões 1.340.700 + aposentadorias 4.400.200 = 5.740.900.", "III é verdadeira: saldo inicial = 5.119.500 − (6.960.400 − 5.740.900) = 3.900.000.", "IV é falsa: resultado financeiro = 5.119.500 − 3.900.000 = 1.219.500, não 2.560.200."], "calculation": "Receita = R$ 6.960.400; despesa = R$ 5.740.900; saldo inicial = R$ 3.900.000; resultado financeiro = R$ 1.219.500.", "correct_answer": "B — II e III, apenas.", "why_wrong": "A inclui I; C inclui IV; D considera I; E não corresponde à combinação correta.", "basis": "MCASP — Balanço Financeiro.", "fafipa_trap": "No RPPS, pensões e aposentadorias são despesas; receitas de contribuições e patrimoniais entram como receitas orçamentárias quando assim classificadas no enunciado.", "verification": "Cálculo reproduzido."}'::jsonb WHERE id='1335898';
UPDATE questoes SET resolution='{"what_it_tests": "Identificar onde a inscrição de Restos a Pagar Não Processados aparece no Balanço Financeiro.", "rule": "A inscrição de restos a pagar é registrada no BF como ingresso extraorçamentário, pois não constitui receita orçamentária do exercício.", "reasoning": ["A inscrição de RPNP não é nova receita orçamentária.", "No BF ela compõe os recebimentos extraorçamentários.", "Logo, a alternativa E é a correta."], "calculation": "Não há cálculo.", "correct_answer": "E — Recebimentos Extraorçamentários.", "why_wrong": "A confunde inscrição de RP com receita; B é a despesa orçamentária; C é transferência financeira; D trata de pagamentos, não de inscrição.", "basis": "MCASP — Balanço Financeiro e Restos a Pagar.", "fafipa_trap": "“Inscrição” de RP entra pelo lado dos ingressos; “pagamento” de RP entra pelos dispêndios extraorçamentários.", "verification": "Conceito conferido."}'::jsonb WHERE id='1336844';
UPDATE questoes SET resolution='{"what_it_tests": "Calcular resultado patrimonial em questão que fornece receitas e despesas orçamentárias/financeiras.", "rule": "O resultado patrimonial da DVP não é simplesmente o resultado orçamentário; depende das variações patrimoniais.", "reasoning": ["A questão apresenta receitas correntes e de capital e informações de pagamentos/empregos de exercícios anteriores.", "Com a composição indicada no material, o resultado patrimonial apontado pelo gabarito é R$ 3.000.", "A diferença decorre da exclusão de itens que não representam VPA/VPD do período na mesma base patrimonial."], "calculation": "Resultado indicado: R$ 3.000,00. A extração não apresenta uma DVP completa para reconstruir cada componente com segurança.", "correct_answer": "D — R$ 3.000,00.", "why_wrong": "As demais alternativas não correspondem ao resultado indicado pelo tratamento patrimonial das informações.", "basis": "Lei nº 4.320/1964; MCASP — DVP e regimes contábeis.", "fafipa_trap": "Não transformar automaticamente resultado orçamentário ou financeiro em resultado patrimonial.", "verification": "Conferir a memória de cálculo na fonte original; a tabela textual não permite reconstituir todos os componentes com segurança."}'::jsonb WHERE id='1054692';
UPDATE questoes SET resolution='{"what_it_tests": "Calcular resultado patrimonial da DVP.", "rule": "Resultado patrimonial = VPA − VPD.", "reasoning": ["VPA = 522.770 + 123.450 + 265.480 + 99.750 + 240.230 + 49.990 = 1.301.670.", "VPD = 162.610 + 12.180 + 26.400 + 168.160 = 369.350.", "Resultado = 932.320."], "calculation": "R$ 1.301.670 − R$ 369.350 = R$ 932.320.", "correct_answer": "B — R$ 932.320,00.", "why_wrong": "As demais alternativas não resultam do confronto correto entre VPA e VPD.", "basis": "MCASP — DVP.", "fafipa_trap": "Não confundir transferências concedidas com receita nem retirar ganhos com alienação do conjunto das VPA.", "verification": "Cálculo reproduzido."}'::jsonb WHERE id='825571';
UPDATE questoes SET resolution='{"what_it_tests": "Determinar a variação do saldo em espécie no Balanço Financeiro.", "rule": "No BF, a inscrição de restos a pagar é ingresso extraorçamentário e pagamentos de RP e devoluções de caução são dispêndios; esses itens alteram a variação do saldo em espécie.", "reasoning": ["Receita arrecadada: +4.700.000.", "Despesa empenhada: −3.700.000.", "Inscrição de RP: +550.000 como ingresso extraorçamentário.", "Devolução de caução: −200.000.", "Pagamento de RP: −950.000.", "Variação = 4.700.000 − 3.700.000 + 550.000 − 200.000 − 950.000 = +400.000."], "calculation": "Aumento = R$ 400.000,00.", "correct_answer": "A — Aumentado em R$ 400.000,00.", "why_wrong": "As demais alternativas desconsideram ou classificam incorretamente a inscrição de RP e/ou os dispêndios extraorçamentários.", "basis": "MCASP — Balanço Financeiro; Lei nº 4.320/1964, art. 103.", "fafipa_trap": "Despesa empenhada não é necessariamente igual ao pagamento; para o BF, é preciso considerar os fluxos efetivos e os RP.", "verification": "Cálculo reproduzido."}'::jsonb WHERE id='1054706';
UPDATE questoes SET resolution='{"what_it_tests": "Julgar assertivas sobre iniciativa, emendas e natureza autorizativa do orçamento.", "rule": "PPA, LDO e LOA são de iniciativa do Executivo; emendas parlamentares precisam respeitar as regras constitucionais; o orçamento brasileiro mantém componentes autorizativos, embora existam programações de execução obrigatória previstas constitucionalmente.", "reasoning": ["I: Falsa. A iniciativa das leis orçamentárias é do Poder Executivo, não do Legislativo.", "II: Verdadeira no sentido da jurisprudência indicada: a iniciativa do Executivo não impede toda e qualquer emenda parlamentar, desde que observadas as restrições constitucionais.", "III: Verdadeira como descrição da regra geral do orçamento autorizativo, ressalvadas as hipóteses de execução obrigatória."], "calculation": "Não há cálculo.", "correct_answer": "C — F, V, V.", "why_wrong": "A, B e D classificam pelo menos uma assertiva incorretamente.", "basis": "Constituição Federal, arts. 165 e 166; jurisprudência do STF sobre emendas orçamentárias.", "fafipa_trap": "Não confundir iniciativa privativa do Executivo com proibição absoluta de emendas parlamentares.", "verification": "A questão envolve jurisprudência; a classificação segue o gabarito registrado e a formulação do enunciado."}'::jsonb WHERE id='563073';
UPDATE questoes SET resolution='{"what_it_tests": "Associar PPA, LDO e LOA às suas funções.", "rule": "PPA organiza políticas e objetivos para quatro anos; LDO estabelece metas e prioridades e orienta a LOA; LOA estima receitas e fixa despesas para o exercício.", "reasoning": ["A primeira descrição é da LDO: metas/prioridades, orientação da LOA e alterações tributárias.", "A segunda é do PPA: políticas públicas e planejamento de quatro anos.", "A terceira é da LOA: orçamento anual e execução das dotações.", "Sequência: II, I, III."], "calculation": "Não há cálculo.", "correct_answer": "B — II, I, III.", "why_wrong": "As outras sequências trocam as funções dos instrumentos.", "basis": "Constituição Federal, art. 165.", "fafipa_trap": "Memorize o horizonte: PPA = 4 anos; LDO = ponte/prioridades; LOA = exercício anual.", "verification": "Conceito conferido."}'::jsonb WHERE id='3013720';
UPDATE questoes SET resolution='{"what_it_tests": "Identificar a demonstração que evidencia a movimentação financeira e os saldos de caixa.", "rule": "O Balanço Financeiro evidencia receitas e despesas orçamentárias, ingressos e dispêndios extraorçamentários e saldos de caixa.", "reasoning": ["O enunciado descreve exatamente o objeto do Balanço Financeiro.", "Logo, a demonstração correta é o BF."], "calculation": "Não há cálculo.", "correct_answer": "B — No Balanço Financeiro.", "why_wrong": "BP evidencia situação patrimonial; BO confronta previsão e execução orçamentária; DFC evidencia fluxos de caixa por atividades.", "basis": "Lei nº 4.320/1964, art. 103; MCASP.", "fafipa_trap": "“Movimentação financeira” e “saldo de caixa” apontam para BF, não para BO.", "verification": "Conceito conferido."}'::jsonb WHERE id='635046';
UPDATE questoes SET resolution='{"what_it_tests": "Reconhecer a definição do Balanço Financeiro.", "rule": "O BF evidencia receitas e despesas orçamentárias, ingressos e dispêndios extraorçamentários, conjugados com saldos de caixa anterior e seguinte.", "reasoning": ["A alternativa B reproduz a definição do BF.", "A trata do Balanço Orçamentário.", "C descreve a DFC.", "D descreve o Balanço Patrimonial.", "E trata da DVP."], "calculation": "Não há cálculo.", "correct_answer": "B.", "why_wrong": "Cada alternativa errada descreve outra demonstração contábil.", "basis": "Lei nº 4.320/1964, art. 103; MCASP.", "fafipa_trap": "Diferenciar “previsão x execução” (BO) de “movimentação financeira” (BF).", "verification": "Conceito conferido."}'::jsonb WHERE id='924192';
UPDATE questoes SET resolution='{"what_it_tests": "Identificar o conceito de destinação vinculada de recursos no Balanço Financeiro.", "rule": "A classificação por destinação de recursos relaciona a origem do recurso à sua aplicação, distinguindo destinação ordinária e vinculada.", "reasoning": ["Quando há vinculação a finalidade específica estabelecida em lei/norma, trata-se de destinação vinculada.", "A alternativa D corresponde ao conceito pedido."], "calculation": "Não há cálculo.", "correct_answer": "D — Destinação Vinculada.", "why_wrong": "A e B são tipos de fluxos no BF, não classificações de destinação; C é a categoria oposta à vinculada.", "basis": "MCASP — classificação por fonte/destinação de recursos e Balanço Financeiro.", "fafipa_trap": "“Atrelar origem e aplicação a finalidade específica” = vinculação.", "verification": "Conceito conferido."}'::jsonb WHERE id='938456';
UPDATE questoes SET resolution='{"what_it_tests": "Identificar erro conceitual na definição de variações patrimoniais aumentativas e diminutivas.", "rule": "Variações patrimoniais aumentativas aumentam o patrimônio líquido; variações diminutivas reduzem o patrimônio líquido. Desvalorização, redução a valor recuperável e perdas são exemplos de VPD, não de VPA.", "reasoning": ["O enunciado chama de “Aumentativas” um conjunto de fenômenos descritos como perdas e desvalorizações.", "Esses fenômenos representam variações patrimoniais diminutivas.", "Portanto, a afirmação apresentada está errada."], "calculation": "Não há cálculo.", "correct_answer": "E — Errado.", "why_wrong": "A afirmação não pode ser considerada correta porque inverte VPA e VPD.", "basis": "MCASP — Demonstração das Variações Patrimoniais; Estrutura Conceitual/NBC TSP.", "fafipa_trap": "A banca troca os sinais econômicos: perda/desvalorização reduz PL e, portanto, é VPD.", "verification": "Conceito conferido."}'::jsonb WHERE id='3082515';
UPDATE questoes SET resolution='{"what_it_tests": "Identificar a natureza correta das variações patrimoniais na DVP.", "rule": "Desvalorização e perda de ativos e incorporação de passivos são variações patrimoniais diminutivas (VPD). Operações financeiras como descontos obtidos, juros auferidos e prêmios de resgate de títulos integram variações patrimoniais aumentativas (VPA).", "reasoning": ["O enunciado atribui à rubrica “Desvalorização e Perda de Ativos e Incorporação de Passivos” uma definição ligada a operações financeiras aumentativas.", "A primeira parte é própria de VPD, enquanto descontos obtidos e juros auferidos são exemplos de VPA.", "Logo, a definição apresentada está incorreta."], "calculation": "Não há cálculo.", "correct_answer": "E — Errado.", "why_wrong": "A afirmação mistura uma rubrica de VPD com características de VPA.", "basis": "MCASP — Demonstração das Variações Patrimoniais; NBC TSP/Estrutura Conceitual.", "fafipa_trap": "A banca troca VPA por VPD e mistura exemplos de naturezas opostas.", "verification": "Conceito compatível com a classificação das VPA e VPD na DVP."}'::jsonb WHERE id='3082519';
UPDATE questoes SET resolution='{"what_it_tests": "Identificar a classificação das contribuições na DVP.", "rule": "Contribuições constituem variações patrimoniais aumentativas quando representam ingressos que aumentam o patrimônio líquido; não são variações patrimoniais diminutivas relativas a impostos e taxas.", "reasoning": ["O enunciado afirma que “Contribuições” seriam VPD.", "Na DVP, contribuições aparecem entre as variações patrimoniais aumentativas.", "Portanto, a definição apresentada está incorreta."], "calculation": "Não há cálculo.", "correct_answer": "E — Errado.", "why_wrong": "O erro está em classificar contribuições como VPD.", "basis": "MCASP — Demonstração das Variações Patrimoniais.", "fafipa_trap": "Troca a natureza aumentativa por diminutiva.", "verification": "Conceito compatível com a estrutura da DVP."}'::jsonb WHERE id='3132869';
UPDATE questoes SET resolution='{"what_it_tests": "Identificar o conteúdo da rubrica Tributárias na DVP.", "rule": "Variações patrimoniais diminutivas tributárias correspondem a tributos suportados pelo ente, enquanto contribuições sociais, de intervenção no domínio econômico e de iluminação pública não são, por si, a definição apresentada no item.", "reasoning": ["O item define VPD Tributárias como sendo contribuições sociais, CIDE e contribuição para iluminação pública.", "A rubrica tributárias deve refletir a natureza de tributos suportados pelo ente, e a formulação do item mistura contribuições com a classificação tributária.", "Assim, a afirmação está incorreta."], "calculation": "Não há cálculo.", "correct_answer": "E — Errado.", "why_wrong": "A definição apresentada não corresponde à rubrica de VPD Tributárias.", "basis": "MCASP — Demonstração das Variações Patrimoniais.", "fafipa_trap": "A banca usa espécies de receitas/contribuições para tentar redefinir uma rubrica de VPD.", "verification": "Classificação conceitual da DVP."}'::jsonb WHERE id='3132877';
UPDATE questoes SET resolution='{"what_it_tests": "Identificar onde são registrados ingressos extraorçamentários no Balanço Financeiro.", "rule": "Ingressos extraorçamentários são recursos que não integram a receita orçamentária e que, em regra, serão restituídos em momento próprio. No Balanço Financeiro aparecem em Recebimentos Extraorçamentários.", "reasoning": ["Consignações, fianças e cauções são exemplos de ingressos extraorçamentários.", "Eles não constituem receita orçamentária do ente.", "No Balanço Financeiro, integram o grupo Recebimentos Extraorçamentários."], "calculation": "Não há cálculo.", "correct_answer": "C — Recebimentos Extraorçamentários.", "why_wrong": "A, B e D não representam o grupo específico destinado aos ingressos extraorçamentários descritos.", "basis": "Lei nº 4.320/1964, art. 103; estrutura do Balanço Financeiro.", "fafipa_trap": "Não confundir ingresso financeiro com receita orçamentária.", "verification": "Compatível com a estrutura do Balanço Financeiro."}'::jsonb WHERE id='923437';
UPDATE questoes SET resolution='{"what_it_tests": "Identificar a demonstração que evidencia o resultado patrimonial.", "rule": "A Demonstração das Variações Patrimoniais evidencia as alterações verificadas no patrimônio e indica o resultado patrimonial do período.", "reasoning": ["O enunciado procura a demonstração que evidencia o resultado patrimonial.", "Essa função pertence à DVP.", "Logo, a alternativa A é a correta."], "calculation": "Não há cálculo.", "correct_answer": "A — Na Demonstração das Variações Patrimoniais (DVP).", "why_wrong": "BF e BO possuem objetivos distintos; DMPL tem finalidade própria relacionada às mutações do patrimônio líquido.", "basis": "Lei nº 4.320/1964, art. 104; MCASP — demonstrações contábeis aplicadas ao setor público.", "fafipa_trap": "Confundir resultado patrimonial com resultado orçamentário ou financeiro.", "verification": "Conceito diretamente compatível com a DVP."}'::jsonb WHERE id='923438';
UPDATE questoes SET resolution='{"what_it_tests": "Reconhecer a definição legal do Balanço Financeiro.", "rule": "O Balanço Financeiro evidencia receitas e despesas orçamentárias, recebimentos e pagamentos extraorçamentários e os saldos em espécie do exercício anterior e para o seguinte.", "reasoning": ["O enunciado reproduz a estrutura clássica do Balanço Financeiro.", "A presença simultânea de operações orçamentárias, extraorçamentárias e saldos em espécie caracteriza o BF.", "Portanto, a alternativa A é correta."], "calculation": "Não há cálculo.", "correct_answer": "A — Balanço Financeiro.", "why_wrong": "Balanço Patrimonial e Balanço Orçamentário possuem conteúdos diferentes.", "basis": "Lei nº 4.320/1964, art. 103.", "fafipa_trap": "A banca descreve a demonstração literalmente e troca o nome nas alternativas.", "verification": "Definição compatível com o art. 103."}'::jsonb WHERE id='927062';
UPDATE questoes SET resolution='{"what_it_tests": "Relacionar PPA, LDO e LOA às disposições do art. 165 da Constituição.", "rule": "PPA estabelece diretrizes, objetivos e metas para despesas de capital e programas continuados; LDO compreende metas e prioridades e orienta a elaboração da LOA; LOA compreende, entre outros, orçamento fiscal.", "reasoning": ["I corresponde ao PPA: diretrizes, objetivos e metas para despesas de capital e programas continuados.", "II corresponde à LDO: metas e prioridades para o exercício seguinte.", "III corresponde à LOA: orçamento anual, incluindo o orçamento fiscal.", "A associação é I-B, II-C e III-A."], "calculation": "Não há cálculo.", "correct_answer": "D — I-B, II-C e III-A.", "why_wrong": "As demais alternativas trocam as funções constitucionais de PPA, LDO e LOA.", "basis": "Constituição Federal de 1988, art. 165.", "fafipa_trap": "Memorizar a função de cada instrumento, especialmente a diferença entre planejamento plurianual e anual.", "verification": "Compatível com o art. 165 da CF."}'::jsonb WHERE id='942393';
UPDATE questoes SET resolution='{"what_it_tests": "Identificar os requisitos da LRF para renúncia de receita.", "rule": "A renúncia de receita deve observar as condições do art. 14 da LRF, incluindo estimativa do impacto orçamentário-financeiro e, conforme a hipótese, medidas de compensação.", "reasoning": ["Isenções e anistias podem configurar renúncia de receita.", "O art. 14 exige estimativa do impacto orçamentário-financeiro e estabelece condições adicionais para a renúncia.", "Entre as alternativas, a E é a que corresponde a essa exigência."], "calculation": "Não há cálculo.", "correct_answer": "E — estimativa de impacto orçamentário-financeiro e adoção de medidas de compensação.", "why_wrong": "As demais alternativas criam requisitos que não correspondem ao conjunto de exigências do art. 14.", "basis": "Lei Complementar nº 101/2000 (LRF), art. 14.", "fafipa_trap": "Não reduzir o art. 14 à simples autorização legislativa; é preciso observar as condições fiscais previstas na LRF.", "verification": "Compatível com o art. 14 da LRF."}'::jsonb WHERE id='3876593';
UPDATE questoes SET resolution='{"what_it_tests": "Aplicar o art. 14 da LRF a benefício tributário com renúncia de receita.", "rule": "A concessão ou ampliação de incentivo ou benefício tributário que implique renúncia de receita deve estar acompanhada da estimativa do impacto orçamentário-financeiro no exercício em que iniciar vigência e nos dois seguintes, além das demais condições do art. 14.", "reasoning": ["O caso descreve benefício tributário com potencial redução de arrecadação.", "O art. 14 exige estimativa de impacto no exercício de início de vigência e nos dois seguintes.", "Portanto, a alternativa A reproduz corretamente essa exigência."], "calculation": "Não há cálculo.", "correct_answer": "A — estimativa no exercício de início e nos dois seguintes, além das demais condições legais.", "why_wrong": "B, C, D e E restringem ou afastam requisitos expressamente previstos na LRF.", "basis": "Lei Complementar nº 101/2000 (LRF), art. 14.", "fafipa_trap": "A banca troca o horizonte de três exercícios por apenas o exercício inicial.", "verification": "Compatível com o art. 14 da LRF."}'::jsonb WHERE id='4113527';
UPDATE questoes SET resolution='{"what_it_tests": "Identificar conceitos de dívida consolidada, DCL e operações de crédito.", "rule": "Dívida Pública Consolidada é o montante das obrigações financeiras definidas no art. 29 da LRF. DCL corresponde à dívida consolidada deduzidas as disponibilidades de caixa e demais haveres financeiros, conforme a metodologia aplicável. Operações mobiliárias decorrem da emissão de títulos; contratuais decorrem de contratos ou instrumentos jurídicos equivalentes.", "reasoning": ["I apresenta a definição de dívida consolidada.", "II apresenta a lógica de cálculo da dívida consolidada líquida.", "III define operações de crédito mobiliárias pela emissão de títulos públicos.", "IV define operações de crédito contratuais pela contratação de obrigações financeiras.", "As quatro afirmações estão corretas."], "calculation": "Não há cálculo.", "correct_answer": "C — I, II, III e IV.", "why_wrong": "A, B e D excluem ao menos uma das afirmações que está correta.", "basis": "LRF, art. 29; MCASP — operações de crédito e dívida pública.", "fafipa_trap": "Diferenciar operação mobiliária (títulos) de operação contratual (contrato/instrumento jurídico).", "verification": "Conceitos compatíveis com a LRF e o MCASP."}'::jsonb WHERE id='3423428';
UPDATE questoes SET resolution='{"what_it_tests": "Identificar o instrumento de planejamento que contém diretrizes, objetivos e metas para despesas de capital e programas continuados.", "rule": "O Plano Plurianual estabelece, de forma regionalizada, diretrizes, objetivos e metas da administração pública para despesas de capital e outras delas decorrentes e para programas de duração continuada.", "reasoning": ["O enunciado reproduz a descrição constitucional do PPA.", "A lei que institui o PPA é o instrumento correspondente.", "Logo, a alternativa D está correta."], "calculation": "Não há cálculo.", "correct_answer": "D — lei que instituir o plano plurianual.", "why_wrong": "LDO trata de metas e prioridades e orienta a LOA; LOA estima receitas e fixa despesas para o exercício.", "basis": "Constituição Federal, art. 165, §1º.", "fafipa_trap": "Confundir PPA com LDO, especialmente por ambas tratarem de metas.", "verification": "Texto compatível com o art. 165, §1º."}'::jsonb WHERE id='3599119';
UPDATE questoes SET resolution='{"what_it_tests": "Identificar o conteúdo que não integra a Lei Orçamentária na forma indicada pela Lei nº 4.320/1964.", "rule": "A Lei nº 4.320/1964 define quadros que integram ou acompanham a Lei do Orçamento. A alternativa A usa a formulação de quadro demonstrativo do programa anual de trabalho como elemento que acompanha a lei, e não como quadro integrante listado no art. 2º.", "reasoning": ["As alternativas B, C e D correspondem a quadros expressamente previstos na disciplina da Lei nº 4.320/1964.", "A alternativa A apresenta o quadro demonstrativo do programa anual de trabalho do Governo em termos de obras e serviços, mas não corresponde ao conjunto de quadros que o art. 2º determina que integre a Lei do Orçamento.", "Por isso, A é a exceção indicada pelo gabarito."], "calculation": "Não há cálculo.", "correct_answer": "A — quadro demonstrativo do programa anual de trabalho do Governo, em termos de realização de obras e prestação de serviços.", "why_wrong": "B, C e D estão entre os quadros expressamente previstos na Lei nº 4.320/1964.", "basis": "Lei nº 4.320/1964, especialmente arts. 2º e seguintes.", "fafipa_trap": "Distinguir “integrará” de “acompanhará” a Lei do Orçamento.", "verification": "Conferir a redação literal no art. 2º e dispositivos correlatos da Lei nº 4.320/1964."}'::jsonb WHERE id='3423434';
UPDATE questoes SET resolution='{"what_it_tests": "Identificar o conceito de empresa controlada na LRF.", "rule": "Empresa controlada é sociedade cuja maioria do capital social com direito a voto pertença, direta ou indiretamente, a ente da Federação.", "reasoning": ["A alternativa A fala em minoria, contrariando a definição.", "B e D ampliam indevidamente o conceito de ente da Federação.", "E altera a definição de empresa estatal dependente.", "C reproduz a definição legal de empresa controlada."], "calculation": "Não há cálculo.", "correct_answer": "C — sociedade cuja maioria do capital social com direito a voto pertença, direta ou indiretamente, a ente da Federação.", "why_wrong": "A inverte maioria/minoria; B e D confundem ente com suas entidades; E altera o conceito de estatal dependente.", "basis": "Lei Complementar nº 101/2000, art. 2º, II.", "fafipa_trap": "A troca de “maioria” por “minoria” é a pegadinha central.", "verification": "Definição legal da LRF."}'::jsonb WHERE id='3998491';
UPDATE questoes SET resolution='{"what_it_tests": "Reconhecer princípio que não integra o conjunto usual associado à responsabilidade na gestão fiscal.", "rule": "A LRF enfatiza planejamento, transparência, controle e responsabilidade na gestão fiscal. Impessoalidade é princípio constitucional da Administração Pública, mas não integra esse conjunto de quatro fundamentos da LRF.", "reasoning": ["Responsabilidade, transparência, planejamento e controle estão associados à gestão fiscal responsável.", "Impessoalidade é princípio do art. 37 da Constituição, não um dos quatro indicados para caracterizar a LRF.", "Logo, D é a alternativa que não apresenta um deles."], "calculation": "Não há cálculo.", "correct_answer": "D — Impessoalidade.", "why_wrong": "A, B, C e E correspondem aos fundamentos tradicionalmente destacados para a LRF.", "basis": "Lei Complementar nº 101/2000, art. 1º, §1º; Constituição Federal, art. 37.", "fafipa_trap": "Confundir princípios gerais da Administração Pública com fundamentos específicos da responsabilidade fiscal.", "verification": "Conceito compatível com a abordagem do art. 1º, §1º, da LRF."}'::jsonb WHERE id='2156881';
UPDATE questoes SET resolution='{"what_it_tests": "Identificar a natureza da LRF segundo o art. 1º.", "rule": "A Lei Complementar nº 101/2000 estabelece normas de finanças públicas voltadas para a responsabilidade na gestão fiscal.", "reasoning": ["O enunciado pede a formulação compatível com o art. 1º.", "A LRF trata de finanças públicas, não privadas.", "Ela estabelece normas para a responsabilidade na gestão fiscal.", "Portanto, C é a alternativa correta."], "calculation": "Não há cálculo.", "correct_answer": "C — a LRF estabelece normas de finanças públicas que visam estabelecer deveres na gerência fiscal.", "why_wrong": "A e D falam em finanças privadas; B diz que a LRF revoga normas, em vez de estabelecer normas.", "basis": "Lei Complementar nº 101/2000, art. 1º.", "fafipa_trap": "Trocar “estabelece normas de finanças públicas” por “revoga normas” ou “finanças privadas”.", "verification": "Compatível com o art. 1º da LRF."}'::jsonb WHERE id='2431366';
UPDATE questoes SET resolution='{"what_it_tests": "Identificar elementos do princípio da gestão fiscal responsável no art. 1º, §1º, da LRF.", "rule": "A responsabilidade na gestão fiscal pressupõe ação planejada e transparente, prevenção de riscos e correção de desvios que afetem o equilíbrio das contas públicas.", "reasoning": ["Planejamento aparece expressamente na ideia de ação planejada.", "Transparência também aparece expressamente na ação transparente.", "Intuição e bem-estar não são os termos que estruturam o §1º.", "Logo, apenas I e II têm relação com o conteúdo citado."], "calculation": "Não há cálculo.", "correct_answer": "C — I e II têm relação com o conteúdo citado.", "why_wrong": "III e IV não correspondem aos elementos descritos no art. 1º, §1º.", "basis": "Lei Complementar nº 101/2000, art. 1º, §1º.", "fafipa_trap": "A banca substitui termos legais por palavras aparentemente positivas, mas que não aparecem na definição.", "verification": "Compatível com o texto do art. 1º, §1º."}'::jsonb WHERE id='2431369';
UPDATE questoes SET resolution='{"what_it_tests": "Aplicar o âmbito de incidência da LRF à União e ao Distrito Federal.", "rule": "A LRF alcança a União, os Estados, o Distrito Federal e os Municípios, abrangendo os Poderes e entidades indicados no art. 1º.", "reasoning": ["A União está submetida à LRF.", "O Distrito Federal também está submetido à LRF.", "Logo, a afirmativa I é correta e a II é incorreta.", "Entre as alternativas, D expressa corretamente que I está correta."], "calculation": "Não há cálculo.", "correct_answer": "D — A afirmativa I está correta.", "why_wrong": "A, B e C não refletem a combinação correta: I é verdadeira e II é falsa.", "basis": "Lei Complementar nº 101/2000, art. 1º.", "fafipa_trap": "A banca tenta retirar o Distrito Federal do alcance da LRF.", "verification": "Compatível com o âmbito de aplicação da LRF."}'::jsonb WHERE id='2431371';
UPDATE questoes SET resolution='{"regra": "A LRF (LC nº 101/2000) alcança a União, os Estados, o Distrito Federal e os Municípios, abrangendo seus Poderes e órgãos e as entidades indicadas no art. 1º, §3º.", "passos": ["A afirmativa I diz que a gestão dos Estados está submetida à LRF.", "A afirmativa II diz o mesmo em relação aos Municípios.", "Ambas estão abrangidas pelo conceito de ente da Federação da LRF."], "calculo": "Não há cálculo.", "correta": "A — as afirmativas I e II estão corretas.", "erradas": ["B) Incorreta porque I também é correta.", "C) Incorreta porque I e II são corretas.", "D) Incorreta porque II também é correta."], "fundamento": "LC nº 101/2000, art. 1º, caput e §3º.", "pegadinha": "A questão tenta induzir a restrição da LRF a determinados entes. Estados e Municípios estão expressamente abrangidos.", "cobranca": "LRF — disposições preliminares."}'::jsonb WHERE id='2431373';
UPDATE questoes SET resolution='{"regra": "A LRF aplica-se a todos os Poderes, inclusive Executivo e Judiciário, dentro de seus respectivos âmbitos.", "passos": ["I: o Poder Executivo está sujeito à LRF — verdadeiro.", "II: afirmar que o Judiciário não está sujeito à LRF é falso.", "Logo, I verdadeira e II falsa."], "calculo": "Não há cálculo.", "correta": "D — a afirmativa II está incorreta e a afirmativa I é correta.", "erradas": ["A) Incorreta: II é falsa.", "B) Incorreta: I é verdadeira.", "C) Incorreta: I não é falsa."], "fundamento": "LC nº 101/2000, art. 1º, §3º, I, que inclui os Poderes e órgãos referidos na lei.", "pegadinha": "“Poder” não significa apenas Executivo. A LRF também disciplina limites e responsabilidades dos demais Poderes.", "cobranca": "LRF — disposições preliminares."}'::jsonb WHERE id='2431378';
UPDATE questoes SET resolution='{"regra": "A LRF alcança os Tribunais de Contas. O art. 1º, §3º inclui expressamente os Tribunais de Contas e respectivos órgãos.", "passos": ["I: TCU está submetido à LRF — verdadeiro.", "II: TCDF não estaria submetido — falso.", "Portanto, I verdadeira e II falsa."], "calculo": "Não há cálculo.", "correta": "C — a afirmativa II está incorreta e a afirmativa I é correta.", "erradas": ["A) Inverte o resultado das assertivas.", "B) Considera I falsa, embora o TCU esteja abrangido.", "D) Considera II verdadeira, contrariando a abrangência da LRF."], "fundamento": "LC nº 101/2000, art. 1º, §3º, I, alínea “a”.", "pegadinha": "A banca troca a ideia de “Tribunal de Contas” por “Poder”. O enquadramento decorre da própria abrangência da LRF.", "cobranca": "LRF — disposições preliminares."}'::jsonb WHERE id='2431380';
UPDATE questoes SET resolution='{"regra": "A LRF alcança os Ministérios Públicos. Portanto, tanto o Ministério Público Estadual quanto o Federal estão abrangidos.", "passos": ["I: MPE submetido à LRF — verdadeiro.", "II: MPF não submetido — falso.", "Resultado: I verdadeira e II falsa."], "calculo": "Não há cálculo.", "correta": "B — a afirmativa II está incorreta e a afirmativa I é correta.", "erradas": ["A) Inverte as assertivas.", "C) Considera II verdadeira.", "D) Considera I falsa."], "fundamento": "LC nº 101/2000, art. 1º, §3º, I, que inclui o Ministério Público.", "pegadinha": "A questão usa a separação entre MP estadual e federal para testar se o candidato sabe que ambos estão abrangidos.", "cobranca": "LRF — disposições preliminares."}'::jsonb WHERE id='2431383';
UPDATE questoes SET resolution='{"regra": "Empresa controlada é a sociedade cuja maioria do capital social com direito a voto pertença, direta ou indiretamente, a ente da Federação.", "passos": ["I reproduz a definição legal de empresa controlada.", "II exige apenas qualquer participação no capital com voto, o que é insuficiente.", "Logo, I verdadeira e II falsa."], "calculo": "Não há cálculo.", "correta": "A — II incorreta; I correta.", "erradas": ["B) Incorreta porque II não corresponde à definição legal.", "C) Incorreta porque I é verdadeira.", "D) Inverte o resultado."], "fundamento": "LC nº 101/2000, art. 2º, II.", "pegadinha": "“Qualquer parte” não basta. A definição exige maioria do capital social com direito a voto.", "cobranca": "LRF — conceitos do art. 2º."}'::jsonb WHERE id='2431386';
UPDATE questoes SET resolution='{"regra": "A União, os Estados, o Distrito Federal e os Municípios são entes da Federação para fins da LRF. “Empresa controlada” é conceito distinto.", "passos": ["I: União é ente da Federação — verdadeiro.", "II: Estado é uma empresa controlada — falso; Estado é ente federativo, não empresa.", "Logo, I verdadeira e II falsa."], "calculo": "Não há cálculo.", "correta": "B — II incorreta e I correta.", "erradas": ["A) Inverte as duas assertivas.", "C) Considera Estado como empresa controlada.", "D) Considera falsa uma afirmação correta sobre a União."], "fundamento": "LC nº 101/2000, art. 2º, I e II.", "pegadinha": "Não confunda “ente da Federação” com “empresa controlada”. São categorias jurídicas diferentes na própria LRF.", "cobranca": "LRF — conceitos do art. 2º."}'::jsonb WHERE id='2431388';
UPDATE questoes SET resolution='{"regra": "A Receita Corrente Líquida é apurada pelo somatório das receitas arrecadadas no mês de referência e nos onze anteriores, excluídas as duplicidades e as deduções previstas na lei.", "passos": ["I afirma “independente de duplicidades” — errado.", "II determina a exclusão das duplicidades — correto.", "Portanto, I falsa e II verdadeira."], "calculo": "Janela: mês de referência + 11 meses anteriores = 12 meses ao todo.", "correta": "D — I incorreta e II correta.", "erradas": ["A) I não é correta.", "B) II é correta.", "C) I e II não podem ser simultaneamente corretas."], "fundamento": "LC nº 101/2000, art. 2º, IV e §3º.", "pegadinha": "Memorize “mês de referência + 11 anteriores” e “excluídas as duplicidades”.", "cobranca": "LRF — Receita Corrente Líquida."}'::jsonb WHERE id='2431391';
UPDATE questoes SET resolution='{"regra": "A LC nº 101/2000 é denominada Lei de Responsabilidade Fiscal (LRF).", "passos": ["Identifique a espécie normativa: LC nº 101/2000.", "A própria lei é conhecida como Lei de Responsabilidade Fiscal."], "calculo": "Não há cálculo.", "correta": "B — Lei de Responsabilidade Fiscal.", "erradas": ["A) Lei Orgânica não é a denominação da LC nº 101/2000.", "C) Não é Lei Penal.", "D) É lei complementar, não ordinária.", "E) Não é legislação trabalhista."], "fundamento": "LC nº 101, de 4 de maio de 2000.", "pegadinha": "A alternativa D pode confundir porque a lei estabelece normas gerais de finanças públicas, mas sua espécie é lei complementar.", "cobranca": "LRF — identificação e disposições iniciais."}'::jsonb WHERE id='924736';
UPDATE questoes SET resolution='{"regra": "A LRF define empresa controlada, empresa estatal dependente e Receita Corrente Líquida no art. 2º. A RCL considera o mês de referência e os onze anteriores, com exclusão das duplicidades.", "passos": ["I é falsa: RCL não é apenas tributos + transferências correntes.", "II é verdadeira: corresponde à definição de empresa controlada.", "III é verdadeira: corresponde à definição de empresa estatal dependente.", "IV é falsa: a lei fala no mês de referência e nos onze anteriores, e não “doze anteriores”; além disso, não se incluem duplicidades.", "Restam II e III."], "calculo": "RCL: 1 mês de referência + 11 meses anteriores = 12 meses.", "correta": "B — apenas II e III.", "erradas": ["A) I é falsa.", "C) I e IV são falsas.", "D) I e IV são falsas.", "E) I e IV tornam a alternativa incorreta."], "fundamento": "LC nº 101/2000, art. 2º, II, III e IV, e §3º.", "pegadinha": "A banca altera pequenos trechos literais: “doze anteriores” e “incluindo duplicidades” são sinais de erro.", "cobranca": "LRF — conceitos e RCL."}'::jsonb WHERE id='1061036';
UPDATE questoes SET resolution='{"regra": "A LDO, na Constituição, estabelece diretrizes de política fiscal e respectivas metas, orienta a elaboração da LOA e dispõe sobre a política de aplicação das agências financeiras oficiais de fomento. PPA é que estabelece diretrizes, objetivos e metas da administração federal para despesas de capital e programas de duração continuada.", "passos": ["I: verdadeiro — a LDO estabelece diretrizes de política fiscal e metas, conforme art. 165, §2º, na redação constitucional vigente.", "II: falso — a LDO orienta a elaboração da LOA, não do PPA.", "III: verdadeiro — cabe à LDO estabelecer a política de aplicação das agências financeiras oficiais de fomento.", "IV: falso — a descrição regionalizada de diretrizes, objetivos e metas para despesas de capital pertence ao PPA.", "V: falso — programas de duração continuada também integram o conteúdo do PPA."], "calculo": "Sequência: V, F, V, F, F.", "correta": "B — V, F, V, F, F.", "erradas": ["A) Começa com F e erra o item I.", "C) Inverte os itens I e III.", "D) Considera I, II e III falsos.", "E) Considera II e V verdadeiros."], "fundamento": "CF/88, art. 165, §1º e §2º.", "pegadinha": "A principal troca é LDO × PPA: LDO orienta a LOA; PPA fixa diretrizes, objetivos e metas de médio prazo.", "cobranca": "AFO — LDO e sistema constitucional de planejamento."}'::jsonb WHERE id='3600655';
UPDATE questoes SET resolution='{"regra": "A Lei de Diretrizes Orçamentárias compreende as metas e prioridades da administração pública e orienta a elaboração da Lei Orçamentária Anual.", "passos": ["PPA é instrumento plurianual.", "LDO faz a ponte entre planejamento e orçamento anual.", "LOA estima receitas e fixa despesas.", "RREO e RGF são relatórios de execução e gestão fiscal, não instrumentos que definem metas e prioridades para orientar a LOA."], "calculo": "Não há cálculo.", "correta": "A — Lei de Diretrizes Orçamentárias.", "erradas": ["B) PPA tem horizonte plurianual e não exerce essa função anual específica.", "C) RREO é relatório de execução orçamentária.", "D) RGF é relatório de gestão fiscal.", "E) LOA materializa o orçamento anual, mas é a LDO que o orienta."], "fundamento": "CF/88, art. 165, §2º.", "pegadinha": "A banca explora a proximidade entre LDO e LOA: quem orienta a elaboração da LOA é a LDO.", "cobranca": "AFO — LDO."}'::jsonb WHERE id='3862420';
UPDATE questoes SET resolution='{"regra": "Na renúncia de receita, o art. 14 da LRF exige estimativa do impacto orçamentário-financeiro no exercício de início da vigência e nos dois seguintes, além do atendimento às condições legais.", "passos": ["A alternativa A exige cumulativamente LOA + compensação, mas a lei admite caminhos alternativos.", "B apresenta os dois caminhos: demonstrar que a renúncia foi considerada na estimativa da receita da LOA sem afetar metas fiscais, ou adotar medidas de compensação por aumento de receita.", "C está errada porque inclui concessão de isenção em caráter geral na lista de renúncias do art. 14, que trata de isenção em caráter não geral.", "D é errada porque não há dispensa automática da estimativa de impacto."], "calculo": "Impacto: exercício em que a renúncia começa + dois exercícios seguintes.", "correta": "B — é a alternativa compatível com o art. 14 da LRF.", "erradas": ["A) Exige simultaneamente condições que a lei apresenta como alternativas.", "C) Inclui isenção em caráter geral, quando a definição legal menciona isenção em caráter não geral.", "D) A compensação não elimina a exigência da estimativa de impacto."], "fundamento": "LC nº 101/2000, art. 14.", "pegadinha": "Decore a estrutura “estimativa de impacto + pelo menos uma das condições legais”.", "cobranca": "LRF — renúncia de receita."}'::jsonb WHERE id='3599136';
UPDATE questoes SET resolution='{"regra": "As previsões de receita devem observar normas técnicas e legais e considerar fatores relevantes. A LRF também disciplina o prazo e a disponibilização das estimativas, metas de arrecadação e reestimativa pelo Legislativo.", "passos": ["A está errada: a lei fala em evolução nos três anos anteriores e projeção para os dois seguintes, não “últimos dois”.", "B está errada: o prazo indicado pela LRF é 45 dias antes do prazo final para encaminhamento das propostas orçamentárias, não 60.", "C está errada: o prazo é até trinta dias após a publicação dos orçamentos, não sessenta.", "D está errada: operações de crédito não podem superar despesas de capital, ressalvada a exceção constitucional específica.", "E reproduz a regra da reestimativa pelo Legislativo apenas diante de erro ou omissão de ordem técnica ou legal."], "calculo": "Não há cálculo.", "correta": "E.", "erradas": ["A) Erra os períodos de evolução/projeção.", "B) Erra o prazo de 45 dias.", "C) Erra o prazo de 30 dias.", "D) Contraria a regra de ouro."], "fundamento": "LC nº 101/2000, arts. 12 e 13; CF/88, art. 167, III.", "pegadinha": "A FAFIPA costuma trocar prazos: confira 45 dias, 30 dias e os períodos de evolução/projeção.", "cobranca": "LRF — previsão e arrecadação da receita."}'::jsonb WHERE id='3600643';
UPDATE questoes SET resolution='{"regra": "A renúncia de receita deve observar o art. 14 da LRF, incluindo estimativa do impacto orçamentário-financeiro e uma das condições previstas no dispositivo.", "passos": ["A exige aprovação legislativa e dispensa requisitos fiscais — errado.", "B reúne estimativa de impacto e a comprovação de que a renúncia foi considerada na LOA sem afetar metas fiscais ou adoção de medidas de compensação — correto.", "C e D dispensam requisitos que a LRF exige."], "calculo": "Não há cálculo.", "correta": "B.", "erradas": ["A) Prazo determinado não elimina as exigências do art. 14.", "C) Interesse público, sozinho, não dispensa os requisitos fiscais.", "D) Superávit anterior não autoriza automaticamente a renúncia sem observância do art. 14."], "fundamento": "LC nº 101/2000, art. 14.", "pegadinha": "Superávit passado não substitui a análise do impacto e das condições da LRF.", "cobranca": "LRF — renúncia de receita."}'::jsonb WHERE id='3710395';
UPDATE questoes SET resolution='{"regra": "A renúncia de receita do art. 14 exige estimativa de impacto no exercício inicial e nos dois seguintes e atendimento das condições legais. Se a opção for compensação por aumento de receita, o benefício só entra em vigor após a implementação das medidas.", "passos": ["I é verdadeira.", "II é verdadeira.", "III é verdadeira.", "IV é falsa: interesse público relevante não cria dispensa geral dos requisitos.", "V é verdadeira: remissão, anistia e isenções específicas podem integrar as hipóteses de renúncia do art. 14.", "Logo: I, II, III e V."], "calculo": "Não há cálculo.", "correta": "E — I, II, III e V, apenas.", "erradas": ["A) Exclui III, que é verdadeira no caso de compensação.", "B) Exclui V.", "C) Inclui IV, que é falsa.", "D) Exclui I e V."], "fundamento": "LC nº 101/2000, art. 14.", "pegadinha": "O ponto decisivo é o inciso II do §2º: se a compensação for utilizada, a vigência do benefício depende da implementação das medidas.", "cobranca": "LRF — renúncia de receita."}'::jsonb WHERE id='3930715';
UPDATE questoes SET resolution='{"regra": "Para contratação de operação de crédito, o art. 32, §1º, da LRF exige, entre outras condições, autorização prévia e expressa, observância dos limites do Senado, inclusão dos recursos no orçamento/créditos adicionais e, em operação externa, autorização específica do Senado.", "passos": ["A corresponde a uma condição legal.", "B corresponde a uma condição legal.", "C afirma necessidade de autorização específica do Tribunal de Contas Estadual por operação interna acima de 25%; essa condição não está no art. 32, §1º.", "D corresponde à exigência para operação externa.", "E corresponde à inclusão orçamentária, com a exceção indicada para ARO."], "calculo": "Não há cálculo.", "correta": "C — é a exceção (EXCETO) pedida.", "erradas": ["A) Está prevista na LRF.", "B) Está prevista na LRF.", "D) Está prevista para operação externa.", "E) Está prevista na LRF."], "fundamento": "LC nº 101/2000, art. 32, §1º.", "pegadinha": "A questão pede EXCETO: procure a condição que não aparece no rol legal. Tribunal de Contas Estadual não substitui a autorização constitucional/legal exigida para operação de crédito.", "cobranca": "LRF — operações de crédito."}'::jsonb WHERE id='3339289';
UPDATE questoes SET resolution='{"regra": "O art. 29 da LRF define, entre outros conceitos: dívida pública mobiliária é a representada por títulos; refinanciamento da dívida mobiliária é a emissão de títulos para pagar o principal acrescido da atualização monetária; operação de crédito é o compromisso financeiro nas hipóteses listadas; concessão de garantia é o compromisso de adimplência de obrigação de outro ente/entidade; dívida consolidada ou fundada é o montante das obrigações financeiras para amortização em prazo superior a 12 meses.", "passos": ["I corresponde a dívida pública mobiliária.", "II corresponde a refinanciamento da dívida mobiliária.", "III corresponde a operação de crédito.", "IV corresponde a concessão de garantia.", "V corresponde a dívida pública consolidada ou fundada."], "calculo": "Não há cálculo.", "correta": "C — I: Dívida pública mobiliária; II: Refinanciamento da dívida mobiliária; III: Operação de crédito; IV: Concessão de garantia; V: Dívida pública consolidada ou fundada.", "erradas": ["A) Troca as definições de dívida mobiliária/refinanciamento e também III/V.", "B) Troca III e V.", "D) Troca I/II e usa III como operação de crédito, mas mantém V incorretamente como dívida consolidada? A sequência não corresponde integralmente."], "fundamento": "Lei Complementar nº 101/2000 (LRF), art. 29, incisos I a V.", "pegadinha": "A FAFIPA mistura as definições do art. 29. O ponto-chave é não confundir dívida mobiliária com refinanciamento da dívida mobiliária.", "cobranca": "LRF — definições de dívida e endividamento."}'::jsonb WHERE id='2746549';
UPDATE questoes SET resolution='{"regra": "Concessão de garantia é o compromisso de adimplência de obrigação financeira ou contratual assumida por ente da Federação ou entidade a ele vinculada.", "passos": ["Compare a definição do enunciado com as definições do art. 29 da LRF.", "Ela corresponde literalmente à concessão de garantia."], "calculo": "Não há cálculo.", "correta": "D — Concessão de garantia.", "erradas": ["A) Operação de crédito envolve compromisso financeiro como mútuo, abertura de crédito e outras operações.", "B) Dívida mobiliária refere-se a títulos emitidos.", "C) Dívida fundada é o montante das obrigações financeiras para prazo superior a 12 meses.", "E) Refinanciamento envolve emissão de títulos para pagamento do principal acrescido da atualização monetária."], "fundamento": "LRF, art. 29, IV.", "pegadinha": "A expressão “compromisso de adimplência” é a pista direta para concessão de garantia.", "cobranca": "LRF — definições do art. 29."}'::jsonb WHERE id='992826';
UPDATE questoes SET resolution='{"regra": "As cinco definições do art. 29 da LRF correspondem a: V refinanciamento; II dívida mobiliária; I dívida consolidada; IV concessão de garantia; III operação de crédito.", "passos": ["“Emissão de títulos para pagamento do principal...” = V.", "“Dívida pública representada por títulos...” = II.", "“Montante total... amortização em prazo superior a 12 meses” = I.", "“Compromisso de adimplência...” = IV.", "“Compromisso financeiro assumido em razão de mútuo...” = III."], "calculo": "Não há cálculo.", "correta": "A — V, II, I, IV, III.", "erradas": ["B) Troca I e II na segunda/terceira posições.", "C) Troca IV e III nas duas últimas posições.", "D) Confunde refinanciamento com concessão de garantia na primeira definição."], "fundamento": "LRF, art. 29, I a V.", "pegadinha": "Memorize as palavras-chave de cada inciso, especialmente “títulos” (mobiliária), “principal + atualização” (refinanciamento) e “adimplência” (garantia).", "cobranca": "LRF — classificação das definições do art. 29."}'::jsonb WHERE id='1054366';
UPDATE questoes SET resolution='{"regra": "A descrição corresponde à operação de crédito no art. 29 da LRF.", "passos": ["A definição menciona mútuo, abertura de crédito, emissão/aceite de título, aquisição financiada, antecipação de valores, arrendamento mercantil e derivativos.", "Esse conjunto de hipóteses é a definição legal de operação de crédito."], "calculo": "Não há cálculo.", "correta": "A — Operação de crédito.", "erradas": ["B) Dívida consolidada é o montante das obrigações financeiras com prazo superior a 12 meses.", "C) Concessão de garantia é compromisso de adimplência.", "D) Refinanciamento é emissão de títulos para pagar principal acrescido da atualização monetária."], "fundamento": "LRF, art. 29, III.", "pegadinha": "A longa enumeração do enunciado praticamente reproduz a definição legal de operação de crédito.", "cobranca": "LRF — art. 29, III."}'::jsonb WHERE id='3013730';
UPDATE questoes SET resolution='{"regra": "Dívida pública consolidada ou fundada é o montante total, apurado sem duplicidade, das obrigações financeiras assumidas nas hipóteses legais para amortização em prazo superior a 12 meses.", "passos": ["Compare a definição do enunciado com o art. 29 da LRF.", "A expressão “montante total, apurado sem duplicidade” e “prazo superior a doze meses” identifica a dívida consolidada ou fundada."], "calculo": "Não há cálculo.", "correta": "A — Dívida pública consolidada ou fundada.", "erradas": ["B) Dívida mobiliária é representada por títulos emitidos.", "C) Operação de crédito é o compromisso financeiro nas hipóteses do art. 29, III.", "D) Concessão de garantia é compromisso de adimplência.", "E) Refinanciamento é emissão de títulos para pagamento do principal acrescido da atualização monetária."], "fundamento": "LRF, art. 29, I.", "pegadinha": "A palavra “consolidada/fundada” está ligada ao estoque de obrigações, não à operação individual que gerou o compromisso.", "cobranca": "LRF — dívida consolidada."}'::jsonb WHERE id='924174';
UPDATE questoes SET resolution='{"regra": "A mesma definição de montante total das obrigações financeiras para amortização em prazo superior a 12 meses corresponde à dívida pública consolidada ou fundada.", "passos": ["Identifique a expressão legal do art. 29.", "Ela corresponde à dívida pública consolidada ou fundada."], "calculo": "Não há cálculo.", "correta": "B — Dívida pública consolidada ou fundada.", "erradas": ["A) Concessão de garantia trata do compromisso de adimplência.", "C) Operação de crédito trata do compromisso financeiro assumido em determinadas operações.", "D) Refinanciamento trata da emissão de títulos para pagamento do principal atualizado."], "fundamento": "LRF, art. 29, I.", "pegadinha": "As questões 557 e 558 repetem praticamente a mesma definição com alternativas em ordem diferente.", "cobranca": "LRF — definições do art. 29."}'::jsonb WHERE id='938415';
